import csv, datetime
from collections import defaultdict

def parse_date(s):
    return datetime.date.fromisoformat(s)

def mean(xs):
    return sum(xs)/len(xs) if xs else float('nan')

rows=[]
with open('/app/benchmark/data.csv',newline='',encoding='utf-8') as f:
    r=csv.DictReader(f)
    for row in r:
        row['Retail_Price_USD']=int(row['Retail_Price_USD'])
        row['Resale_Price_USD']=float(row['Resale_Price_USD'])
        row['Profit_Margin_USD']=float(row['Profit_Margin_USD'])
        row['Days_in_Inventory']=int(row['Days_in_Inventory'])
        row['Sale_Date']=parse_date(row['Sale_Date'])
        rows.append(row)

print('avg_retail',mean([r['Retail_Price_USD'] for r in rows]))
print('avg_resale',mean([r['Resale_Price_USD'] for r in rows]))

# colorway avg resale for top 5
by_color=defaultdict(list)
for r in rows:
    by_color[r['Colorway']].append(r['Resale_Price_USD'])
for c in ['Pine Green','Military Blue','Chicago','Sail','Lost & Found']:
    print(c,mean(by_color[c]))
